commands.command:
set -u
test "$(git rev-parse HEAD)" = "578281bf750d7c86792ba4d6ccde505a7678c01f" || exit 1
cd frontend
for MODE in all prod; do
  TMP=$(mktemp /tmp/photomap-npm-audit-XXXXXX.json)
  if [ "$MODE" = prod ]; then npm audit --omit=dev --json >"$TMP" 2>/dev/null || true; else npm audit --json >"$TMP" 2>/dev/null || true; fi
  echo "=== npm audit $MODE ==="
  node - "$TMP" <<'NODE'
const fs=require('fs'); const p=process.argv[2]; let x={}; try{x=JSON.parse(fs.readFileSync(p,'utf8'))}catch(e){console.log('audit-json-unavailable');process.exit(0)}
console.log('summary',JSON.stringify(x.metadata?.vulnerabilities||{}));
for (const [name,v] of Object.entries(x.vulnerabilities||{}).sort((a,b)=>String(a[1].severity).localeCompare(String(b[1].severity)))) {
 const via=(v.via||[]).map(z=>typeof z==='string'?z:(z.title||z.source||'advisory')).slice(0,3);
 console.log(JSON.stringify({name,severity:v.severity,isDirect:v.isDirect,range:v.range,fixAvailable:v.fixAvailable,via}));
}
NODE
  rm -f "$TMP"
done
git status --short

